TABLE I.

No 1.
  t+t+v+x+y+z+\mathrm{\;\&c.}=1t+t+v+x+y+z+\mathrm{\;etc.}=1

No 2.



    \begin{array}{ccccccc}
    t & t & v & x & y & z & \\
    \Vert & \Vert & \Vert & \Vert & \Vert & \Vert & \\
    a & a & b & \frac{1}{2}c+\frac{1}{2}b & \frac{1}{4}d+\frac{1}{4}c+\frac{1}{2}b & \frac{1}{8}e+\frac{1}{8}d+\frac{1}{4}c+\frac{1}{2}b & \mathrm{\&c.}
    \end{array}

    \begin{array}{lll}
    t=a & t=a & v=b \\
    x=\frac{1}{2}c+\frac{1}{2}b & y=\frac{1}{4}d+\frac{1}{4}c+\frac{1}{2}b & z=\frac{1}{8}e+\frac{1}{8}d+\frac{1}{4}c+\frac{1}{2}b\;\mathrm{etc.}
    \end{array}

No 3. Entre



    \begin{array}{r|c}
    0 & a \\ 1 & b \\ 2 & c \\ 3 & d \\ 4 & e \\ \vdots & \vdots
    \end{array}
    \quad
    \left.\begin{aligned}
    a &=\overline{\frac{1}{2}+\frac{1}{4}+\frac{1}{8}+\frac{1}{16}+\mathinner{\ldotp\ldotp\ldotp\ldotp}\frac{1}{2^n}}\times p+\frac{1}{2^n}\times1 \\
    b &=\overline{\frac{1}{2}\times q+\frac{1}{4}+\frac{1}{8}+\frac{1}{16}+\ldots\frac{1}{2^n}}\times p+\frac{1}{2^n}\times1 \\
    c &=\overline{\frac{1}{2}\times r+\frac{1}{4}+\frac{1}{8}+\frac{1}{16}+\ldots\frac{1}{2^n}}\times p+\frac{1}{2^n}\times1 \\
    d &=\overline{\frac{1}{2}\times s+\frac{1}{4}+\frac{1}{8}+\frac{1}{16}+\ldots\frac{1}{2^n}}\times p+\frac{1}{2^n}\times1
    \end{aligned}\right\}

    \begin{array}{r|c}
    0 & a \\ 1 & b \\ 2 & c \\ 3 & d \\ 4 & e \\ \vdots & \vdots
    \end{array}
    \quad
    \left.\begin{aligned}
    a &=\left(\frac{1}{2}+\frac{1}{4}+\frac{1}{8}+\frac{1}{16}+\cdots+\frac{1}{2^n}\right)p+\frac{1}{2^n}\cdot1 \\
    b &=\left(\frac{1}{2}q+\frac{1}{4}+\frac{1}{8}+\frac{1}{16}+\cdots+\frac{1}{2^n}\right)p+\frac{1}{2^n}\cdot1 \\
    c &=\left(\frac{1}{2}r+\frac{1}{4}+\frac{1}{8}+\frac{1}{16}+\cdots+\frac{1}{2^n}\right)p+\frac{1}{2^n}\cdot1 \\
    d &=\left(\frac{1}{2}s+\frac{1}{4}+\frac{1}{8}+\frac{1}{16}+\cdots+\frac{1}{2^n}\right)p+\frac{1}{2^n}\cdot1
    \end{aligned}\right\}

No 4. Sort


    \begin{array}{r|c}
    1 & p \\ 2 & q \\ 3 & r \\ 4 & s \\ \vdots & \vdots
    \end{array}
    \quad\begin{aligned}
    p &=\frac{1}{2^{n-1}}\times v+\frac{1}{2^{n-2}}\times x+\frac{1}{2^{n-3}}\times y+\frac{1}{2^{n-4}}\times z+\ldots \\
    q &=\frac{1}{2^{n-2}}\times x+\frac{1}{2^{n-3}}\times y+\frac{1}{2^{n-4}}\times z+\ldots \\
    r &=\frac{1}{2^{n-3}}\times y+\frac{1}{2^{n-4}}\times z+\ldots \\
    s &=\frac{1}{2^{n-4}}\times z+\ldots
    \end{aligned}

    \begin{array}{r|c}
    1 & p \\ 2 & q \\ 3 & r \\ 4 & s \\ \vdots & \vdots
    \end{array}
    \quad\begin{aligned}
    p &=\frac{1}{2^{n-1}}v+\frac{1}{2^{n-2}}x+\frac{1}{2^{n-3}}y+\frac{1}{2^{n-4}}z+\cdots \\
    q &=\frac{1}{2^{n-2}}x+\frac{1}{2^{n-3}}y+\frac{1}{2^{n-4}}z+\cdots \\
    r &=\frac{1}{2^{n-3}}y+\frac{1}{2^{n-4}}z+\cdots \\
    s &=\frac{1}{2^{n-4}}z+\cdots
    \end{aligned}

    \begin{array}{lll}
    a-b=\frac{1}{2}p-\frac{1}{2}q & =\frac{1}{2^n}\times v & =t-v \\
    b-c=\frac{1}{2}q-\frac{1}{2}r & =\frac{1}{2^{n-1}}\times x & =2v-2x \\
    c-d=\frac{1}{2}r-\frac{1}{2}s & =\frac{1}{2^{n-2}}\times y & =4x-4y \\
    \mathrm{N}^{\mathrm{o}}\,5. & \mathrm{N}^{\mathrm{o}}\,7. & \mathrm{N}^{\mathrm{o}}\,9.
    \end{array}

    \begin{array}{lll}
    a-b=\frac{1}{2}p-\frac{1}{2}q & =\frac{1}{2^n}v & =t-v \\
    b-c=\frac{1}{2}q-\frac{1}{2}r & =\frac{1}{2^{n-1}}x & =2v-2x \\
    c-d=\frac{1}{2}r-\frac{1}{2}s & =\frac{1}{2^{n-2}}y & =4x-4y \\
    \mathrm{N}^{\mathrm{o}}\,5. & \mathrm{N}^{\mathrm{o}}\,7. & \mathrm{N}^{\mathrm{o}}\,9.
    \end{array}


No 6.

    \left.\begin{aligned}
    p-q &=\frac{1}{2^{n-1}}\times v \\
    q-r &=\frac{1}{2^{n-2}}\times x \\
    r-s &=\frac{1}{2^{n-3}}\times y
    \end{aligned}\right\}

    \left.\begin{aligned}
    p-q &=\frac{1}{2^{n-1}}v \\
    q-r &=\frac{1}{2^{n-2}}x \\
    r-s &=\frac{1}{2^{n-3}}y
    \end{aligned}\right\}

No 8.


    \begin{aligned}
    a &=t \\
    b &=v \\
    c &=2x-b=2x-u \\
    d &=4y-c-2b=4y-2x-v
    \end{aligned}


No 10.

    \left.\begin{aligned}
    v &=t\times\frac{2^n}{1+2^n} \\
    x &=v\times\frac{2^n}{1+2^n} \\
    y &=x\times\frac{2^n}{1+2^n}
    \end{aligned}\right\}

    \left.\begin{aligned}
    v &=t\,\frac{2^n}{1+2^n} \\
    x &=v\,\frac{2^n}{1+2^n} \\
    y &=x\,\frac{2^n}{1+2^n}
    \end{aligned}\right\}
